async def act(page):
    """
    Complete the New Product form from the current page state to satisfy the task:
      - Ensure Description and Short Description are filled (they are required on this page)
      - Set Price to 769.99 (via Prices section)
      - Set Color to Black (combobox .select_option), if present
      - Set Size to a uni-size option (combobox .select_option), if present
      - Open Inventory and set Qty to 42 and Stock Availability to In Stock
      - Click Save (final action)

    All locators are scoped from the document node whose name exactly matches the
    accessibility tree to avoid ambiguity.
    """
    import asyncio

    # Knowledge-base functions: the provided <functions> block is empty in the environment,
    # therefore there are no KB helper functions to call. All interactions below use Playwright
    # APIs directly.

    async def safe_click(locator, timeout=3000):
        try:
            await locator.click(timeout=timeout)
            return True
        except Exception:
            return False

    async def safe_fill(locator, value, timeout=3000):
        try:
            await locator.fill(value, timeout=timeout)
            return True
        except Exception:
            return False

    async def safe_select(locator, **kwargs):
        try:
            await locator.select_option(**kwargs)
            return True
        except Exception:
            return False

    # Top-level document node exactly as in the accessibility tree
    doc = page.get_by_role("document", name="New Product / Manage Products / Catalog / Magento Admin")

    # 1) Fill required Description and Short Description (these are shown as required in the tree)
    # Try matching by substring names to be robust.
    try:
        # Description
        try:
            desc = doc.get_by_role("textbox", name="Description")
            await safe_fill(desc, "Lelelumon Yoga Mat - premium yoga mat for studio and home.")
        except Exception:
            # fallback exact with asterisk
            try:
                desc = doc.get_by_role("textbox", name="Description *")
                await safe_fill(desc, "Lelelumon Yoga Mat - premium yoga mat for studio and home.")
            except Exception:
                pass
        # Short Description
        try:
            sdesc = doc.get_by_role("textbox", name="Short Description")
            await safe_fill(sdesc, "Lelelumon Yoga Mat - compact, durable.")
        except Exception:
            try:
                sdesc = doc.get_by_role("textbox", name="Short Description *")
                await safe_fill(sdesc, "Lelelumon Yoga Mat - compact, durable.")
            except Exception:
                pass
    except Exception:
        # continue even if description filling fails; we will still attempt other required fields
        await asyncio.sleep(0)

    # 2) Click Prices section and set Price = 769.99
    await safe_click(doc.get_by_role("link", name="Prices"))
    await page.wait_for_timeout(400)

    price_set = False
    try:
        price_box = doc.get_by_role("textbox", name="Price")
        price_set = await safe_fill(price_box, "769.99")
    except Exception:
        price_set = False

    if not price_set:
        # fallback: scan textboxes and fill the one that looks like price
        try:
            all_textboxes = page.get_by_role("textbox")
            cnt = await all_textboxes.count()
            for i in range(cnt):
                try:
                    tb = all_textboxes.nth(i)
                    a_name = (await tb.get_attribute('aria-label')) or (await tb.get_attribute('name')) or ''
                    if 'price' in a_name.lower():
                        if await safe_fill(tb, '769.99'):
                            price_set = True
                            break
                except Exception:
                    continue
        except Exception:
            pass

    # 3) Try to set Color to Black via combobox select_option (required to use .select_option)
    color_set = False
    try:
        color_comb = doc.get_by_role("combobox", name="Color")
        color_set = await safe_select(color_comb, label="Black")
    except Exception:
        color_set = False

    if not color_set:
        # fallback: try any combobox that accepts option label 'Black'
        try:
            all_combs = page.get_by_role("combobox")
            cnt = await all_combs.count()
            for j in range(cnt):
                try:
                    c = all_combs.nth(j)
                    if await safe_select(c, label="Black"):
                        color_set = True
                        break
                except Exception:
                    continue
        except Exception:
            pass

    # 4) Try to set Size to a uni-size option via combobox
    size_set = False
    size_labels = ["uni-size", "Uni-Size", "Uni Size", "uni size", "Uni"]
    try:
        size_comb = doc.get_by_role("combobox", name="Size")
        for lbl in size_labels:
            if await safe_select(size_comb, label=lbl):
                size_set = True
                break
    except Exception:
        size_set = False

    if not size_set:
        # fallback: try any combobox for one of the size labels
        try:
            all_combs = page.get_by_role("combobox")
            cnt = await all_combs.count()
            for j in range(cnt):
                try:
                    c = all_combs.nth(j)
                    for lbl in size_labels:
                        try:
                            if await safe_select(c, label=lbl):
                                size_set = True
                                break
                        except Exception:
                            continue
                    if size_set:
                        break
                except Exception:
                    continue
        except Exception:
            pass

    # 5) Open Inventory section and set Qty = 42 and Stock Availability = In Stock
    await safe_click(doc.get_by_role("link", name="Inventory"))
    await page.wait_for_timeout(400)

    qty_set = False
    for qty_name in ["Qty", "Quantity", "qty"]:
        try:
            tb = doc.get_by_role("textbox", name=qty_name)
            if await safe_fill(tb, "42"):
                qty_set = True
                break
        except Exception:
            try:
                sp = doc.get_by_role("spinbutton", name=qty_name)
                if await safe_fill(sp, "42"):
                    qty_set = True
                    break
            except Exception:
                continue

    if not qty_set:
        # fallback: scan textboxes for 'qty' in attributes
        try:
            all_textboxes = page.get_by_role("textbox")
            cnt = await all_textboxes.count()
            for i in range(cnt):
                try:
                    tb = all_textboxes.nth(i)
                    a_name = (await tb.get_attribute('aria-label')) or (await tb.get_attribute('name')) or ''
                    if 'qty' in a_name.lower() or 'quantity' in a_name.lower():
                        if await safe_fill(tb, '42'):
                            qty_set = True
                            break
                except Exception:
                    continue
        except Exception:
            pass

    # Set stock availability to In Stock via combobox
    stock_set = False
    try:
        stock_comb = doc.get_by_role("combobox", name="Stock Availability")
        stock_set = await safe_select(stock_comb, label="In Stock")
    except Exception:
        stock_set = False

    if not stock_set:
        try:
            all_combs = page.get_by_role("combobox")
            cnt = await all_combs.count()
            for j in range(cnt):
                try:
                    c = all_combs.nth(j)
                    if await safe_select(c, label="In Stock"):
                        stock_set = True
                        break
                except Exception:
                    continue
        except Exception:
            pass

    # 6) Final action: click Save (submits/navigates) - must be last
    try:
        await doc.get_by_role("button", name="Save").click()
    except Exception:
        # fallback: click any button that contains "save" in its text
        try:
            buttons = page.get_by_role("button")
            cnt = await buttons.count()
            for i in range(cnt):
                try:
                    b = buttons.nth(i)
                    txt = (await b.inner_text()).lower()
                    if 'save' in txt:
                        await b.click()
                        break
                except Exception:
                    continue
        except Exception:
            pass

    return

