                await safe_fill(desc, "Lelelumon Yoga Mat - premium yoga mat for studio and home.")
            except Exception:
                pass
        # Short Description
        try:
            sdesc = doc.get_by_role("textbox", name="Short Description")
            await safe_fill(sdesc, "Lelelumon Yoga Mat - compact, durable.")
        except Exception:
            try:
                sdesc = doc.get_by_role("textbox", name="Short Description *")
                await safe_fill(sdesc, "Lelelumon Yoga Mat - compact, durable.")
